  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * ## Connection lifecycle
 11→ *
 12→ * 1. Connect to `ws://<host>:9900/browser`.
 13→ * 2. Server sends `agent_list` (sidebar metadata) + `task_list`. No
 14→ *    message histories are sent eagerly — this keeps the initial
 15→ *    payload small for fast loading on mobile networks.
 16→ * 3. `initialLoadDone` becomes true after `agent_list` arrives.
 17→ * 4. The first agent is auto-selected if nothing was selected.
 18→ *
 19→ * ## Lazy history loading
 20→ *
 21→ * Message histories are loaded on demand. When `activeAgentId` changes
 22→ * and the agent hasn't been loaded yet, the hook sends
 23→ * `{ type: "request_history", agentId }` and sets `historyLoading = true`.
 24→ * When the server responds with `message_history`, the agent's messages
 25→ * are populated and `historyLoading` becomes false.
 26→ *
 27→ * The `loadedAgents` Set tracks which agents have been fetched so that
 28→ * switching back to a previously viewed agent is instant.
 29→ *
 30→ * ## Resilience features
 31→ *
 32→ * - Handles `message_history` replay from server on demand.
 33→ * - Handles `cli_disconnected` / `cli_connected` events.
 34→ * - Deduplicates messages using a per-agent processed count.
 35→ * - Robust reconnection guard (clears previous timer before scheduling).
 36→ * - Strict mode safe (closingRef prevents spurious reconnects on unmount).
 37→ *
 38→ * ## Logging
 39→ *
 40→ * All WS events are logged with the `[thos-ws]` prefix. Filter by this
 41→ * in the browser console to debug connection and message delivery issues.
 42→ */
 43→
 44→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 45→import type {
 46→  AgentInfo,
 47→  AgentStatus,
 48→  ChatMessage,
 49→  ClaudeAssistant,
 50→  ClaudeControlRequest,
 51→  ClaudeMessage,
 52→  ClaudeResult,
 53→  ClaudeSystemInit,
 54→  ServerMessage,
 55→  ServerMessageHistory,
 56→  ServerTaskList,
 57→  ServerTaskUpdated,
 58→  ServerTaskDeleted,
 59→  Task,
 60→  TaskPriority,
 61→  ToolCallInfo,
 62→  UserQuestion,
 63→} from "@/lib/types";
 64→
 65→/** Connect to the WS server on the same host the page was loaded from. */
 66→const WS_URL =
 67→  typeof window !== "undefined"
 68→    ? `ws://${window.location.hostname}:9900/browser`
 69→    : "ws://localhost:9900/browser";
 70→
 71→/** Per-agent client state. */
 72→export interface AgentClientState {
 73→  status: AgentStatus;
 74→  messages: ChatMessage[];
 75→  /** Raw Claude NDJSON messages for debug view. */
 76→  rawMessages: ClaudeMessage[];
 77→  label: string;
 78→  tmuxSession: string | null;
 79→  createdAt: number;
 80→}
 81→
 82→/**
 83→ * Extract displayable text from a Claude assistant message.
 84→ * Content blocks may be text, tool_use, or tool_result — each is
 85→ * handled defensively since the array structure can vary.
 86→ */
 87→function extractText(msg: ClaudeAssistant): string {
 88→  const blocks = msg.message?.content;
 89→  if (!blocks || !Array.isArray(blocks)) return "";
 90→  return blocks
 91→    .map((b) => {
 92→      if (b.type === "text") return b.text;
 93→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 94→      if (b.type === "tool_result") {
 95→        const c = (b as { content?: unknown }).content;
 96→        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
 97→      }
 98→      return "";
 99→    })
100→    .filter(Boolean)
101→    .join("\n");
102→}
103→
104→/** Module-level counter for generating unique message IDs. */
105→let msgCounter = 0;
106→function nextId() {
107→  return `msg-${Date.now()}-${++msgCounter}`;
108→}
109→
110→/**
111→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
112→ * Used both for live messages and for replaying message_history.
113→ */
114→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
115→  if (relayMsg.type === "relay") {
116→    const msg = relayMsg.message;
117→
118→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
119→      const init = msg as ClaudeSystemInit;
120→      return {
121→        id: nextId(),
122→        role: "system",
123→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
124→        timestamp: Date.now(),
125→      };
126→    }
127→
128→    if (msg.type === "user") {
129→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
130→      // Only render human-typed user messages (string content).
131→      // CLI tool_result messages have array content — these are internal
132→      // protocol messages and are only visible in the raw message viewer.
133→      if (typeof rawContent !== "string") return null;
134→      if (!rawContent.trim()) return null;
135→      return {
136→        id: nextId(),
137→        role: "user",
138→        content: rawContent,
139→        timestamp: Date.now(),
140→      };
141→    }
142→
143→    if (msg.type === "assistant") {
144→      const assistant = msg as ClaudeAssistant;
145→      const text = extractText(assistant);
146→      if (!text) return null;
147→
148→      const blocks = assistant.message?.content ?? [];
149→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
150→      const toolCalls: ToolCallInfo[] = blocks
151→        .filter((b) => b.type === "tool_use")
152→        .map((b) => ({
153→          name: (b as { name: string }).name,
154→          toolUseId: (b as { id: string }).id,
155→        }));
156→      const isToolOnly = !hasText && toolCalls.length > 0;
157→
158→      return {
159→        id: nextId(),
160→        role: "assistant",
161→        content: text,
162→        timestamp: Date.now(),
163→        toolCalls,
164→        isToolOnly,
165→      };
166→    }
167→
168→    if (msg.type === "result") {
169→      const result = msg as ClaudeResult;
170→      const cost = result.total_cost_usd ?? result.cost_usd ?? 0;
171→      const summary = result.is_error
172→        ? `Error: ${result.error}`
173→        : `Done — ${result.num_turns ?? "?"} turns, $${cost.toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
174→      return {
175→        id: nextId(),
176→        role: "system",
177→        content: summary,
178→        timestamp: Date.now(),
179→      };
180→    }
181→
182→    if (msg.type === "control_request") {
183→      const cr = msg as ClaudeControlRequest;
184→
185→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
186→      if (cr.request.tool_name === "AskUserQuestion") {
187→        const input = cr.request.input as { questions?: UserQuestion[] };
188→        const questions = Array.isArray(input.questions) ? input.questions : [];
189→        return {
190→          id: nextId(),
191→          role: "system",
192→          content: "Question from Claude",
193→          timestamp: Date.now(),
194→          userQuestion: {
195→            requestId: cr.request_id,
196→            questions,
197→          },
198→        };
199→      }
200→
201→      return {
202→        id: nextId(),
203→        role: "system",
204→        content: `Tool approval requested: ${cr.request.tool_name}`,
205→        timestamp: Date.now(),
206→        controlRequest: {
207→          id: cr.request_id,
208→          tool_name: cr.request.tool_name,
209→          input: cr.request.input,
210→          description: cr.request.description,
211→        },
212→      };
213→    }
214→  }
215→
216→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
217→    return {
218→      id: nextId(),
219→      role: "system",
220→      content: `Error: ${relayMsg.error}`,
221→      timestamp: Date.now(),
222→    };
223→  }
224→
225→  return null;
226→}
227→
228→/** Console logger with [thos] prefix for easy filtering. */
229→function log(...args: unknown[]) {
230→  console.log("[thos-ws]", ...args);
231→}
232→
233→export function useWebSocket() {
234→  const wsRef = useRef<WebSocket | null>(null);
235→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
236→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
237→  const closingRef = useRef(false);
238→  const [connected, setConnected] = useState(false);
239→  /** True once we've received the initial agent_list from the server. */
240→  const [initialLoadDone, setInitialLoadDone] = useState(false);
241→
242→  // Multi-agent state
243→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
244→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
245→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
246→
247→  // Task state
248→  const [tasks, setTasks] = useState<Task[]>([]);
249→
250→  // Per-agent deduplication: track count of processed messages per agent
251→  // to avoid duplicating messages already in local state during history replay.
252→  const processedCountRef = useRef<Map<string, number>>(new Map());
253→
254→  // Track which agents have had their history loaded (lazy loading).
255→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
256→
257→  /** Immutably update a single agent's state in the Map. */
258→  const updateAgent = useCallback(
259→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
260→      setAgents((prev) => {
261→        const existing = prev.get(agentId);
262→        if (!existing) return prev;
263→        const next = new Map(prev);
264→        next.set(agentId, updater(existing));
265→        return next;
266→      });
267→    },
268→    []
269→  );
270→
271→  const connect = useCallback(() => {
272→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
273→    if (wsRef.current) {
274→      wsRef.current.close();
275→      wsRef.current = null;
276→    }
277→
278→    // Reset dedup counts on new connection — server will send fresh history
279→    processedCountRef.current.clear();
280→    setInitialLoadDone(false);
281→    setLoadedAgents(new Set());
282→
283→    log("connecting to", WS_URL);
284→    const ws = new WebSocket(WS_URL);
285→    wsRef.current = ws;
286→
287→    ws.onopen = () => {
288→      log("connected");
289→      setConnected(true);
290→    };
291→
292→    ws.onclose = () => {
293→      log("disconnected, closingRef =", closingRef.current);
294→      setConnected(false);
295→      wsRef.current = null;
296→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
297→      if (closingRef.current) return;
298→      // Reconnection guard: clear any existing timer before scheduling
299→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
300→      log("scheduling reconnect in 2s");
301→      reconnectTimer.current = setTimeout(() => connect(), 2000);
302→    };
303→
304→    ws.onerror = (e) => {
305→      log("error", e);
306→      // onclose will fire after onerror, which triggers reconnect
307→    };
308→
309→    ws.onmessage = (event) => {
310→      let data: ServerMessage;
311→      try {
312→        data = JSON.parse(event.data as string);
313→      } catch {
314→        return;
315→      }
316→
317→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
318→
319→      // ── task_list: full task list from server ──
320→      if (data.type === "task_list") {
321→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
322→        setTasks((data as ServerTaskList).tasks);
323→        return;
324→      }
325→
326→      // ── task_updated: single task changed ──
327→      if (data.type === "task_updated") {
328→        const updated = (data as ServerTaskUpdated).task;
329→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
330→        return;
331→      }
332→
333→      // ── task_deleted: remove task ──
334→      if (data.type === "task_deleted") {
335→        const deletedId = (data as ServerTaskDeleted).taskId;
336→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
337→        return;
338→      }
339→
340→      // ── message_history: replay full history from server ──
341→      if (data.type === "message_history") {
342→        const historyMsg = data as ServerMessageHistory;
343→        const agentId = historyMsg.agentId;
344→        const serverMessages = historyMsg.messages;
345→        log("message_history:", agentId, serverMessages.length, "raw msgs");
346→
347→        // Convert all server messages to ChatMessages + extract raw Claude messages
348→        const chatMessages: ChatMessage[] = [];
349→        const rawMessages: ClaudeMessage[] = [];
350→        for (const sm of serverMessages) {
351→          if (sm.type === "relay") {
352→            rawMessages.push(sm.message);
353→          }
354→          const cm = relayChatMessage(agentId, sm);
355→          if (cm) chatMessages.push(cm);
356→        }
357→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
358→
359→        // Always replace local messages with server history (source of truth).
360→        setAgents((prev) => {
361→          const existing = prev.get(agentId);
362→          if (!existing) {
363→            log("message_history:", agentId, "agent not in map yet, creating");
364→            const next = new Map(prev);
365→            next.set(agentId, {
366→              status: "idle",
367→              messages: chatMessages,
368→              rawMessages,
369→              label: "",
370→              tmuxSession: null,
371→              createdAt: 0,
372→            });
373→            return next;
374→          }
375→          const next = new Map(prev);
376→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
377→          return next;
378→        });
379→
380→        processedCountRef.current.set(agentId, chatMessages.length);
381→        setLoadedAgents((prev) => {
382→          if (prev.has(agentId)) return prev;
383→          const next = new Set(prev);
384→          next.add(agentId);
385→          return next;
386→        });
387→        return;
388→      }
389→
390→      // ── history_cleared: wipe local messages for this agent ──
391→      if (data.type === "history_cleared") {
392→        updateAgent(data.agentId, (prev) => ({
393→          ...prev,
394→          messages: [],
395→          rawMessages: [],
396→        }));
397→        processedCountRef.current.set(data.agentId, 0);
398→        return;
399→      }
400→
401→      // ── cli_disconnected: show system message ──
402→      if (data.type === "cli_disconnected") {
403→        updateAgent(data.agentId, (prev) => ({
404→          ...prev,
405→          messages: [
406→            ...prev.messages,
407→            {
408→              id: nextId(),
409→              role: "system",
410→              content: "CLI session ended",
411→              timestamp: Date.now(),
412→            },
413→          ],
414→        }));
415→        return;
416→      }
417→
418→      // ── cli_connected: show system message ──
419→      if (data.type === "cli_connected") {
420→        updateAgent(data.agentId, (prev) => {
421→          const isReconnect = prev.messages.length > 0;
422→          return {
423→            ...prev,
424→            messages: [
425→              ...prev.messages,
426→              {
427→                id: nextId(),
428→                role: "system",
429→                content: isReconnect ? "CLI reconnected" : "CLI connected",
430→                timestamp: Date.now(),
431→              },
432→            ],
433→          };
434→        });
435→        return;
436→      }
437→
438→      // ── agent_list: reconcile sidebar state from server ──
439→      if (data.type === "agent_list") {
440→        const serverAgents = data.agents as AgentInfo[];
441→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
442→        setAgents((prev) => {
443→          const next = new Map(prev);
444→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
445→
446→          // Update or add agents from server
447→          for (const info of serverAgents) {
448→            const existing = next.get(info.agentId);
449→            if (existing) {
450→              next.set(info.agentId, {
451→                ...existing,
452→                status: info.status,
453→                tmuxSession: info.tmuxSession,
454→                label: info.label,
455→              });
456→            } else {
457→              next.set(info.agentId, {
458→                status: info.status,
459→                messages: [],
460→                rawMessages: [],
461→                label: info.label,
462→                tmuxSession: info.tmuxSession,
463→                createdAt: info.createdAt,
464→              });
465→            }
466→          }
467→
468→          // Remove agents no longer on the server
469→          for (const id of next.keys()) {
470→            if (!serverIds.has(id)) {
471→              next.delete(id);
472→            }
473→          }
474→
475→          return next;
476→        });
477→        setAgentOrder(serverAgents.map((a) => a.agentId));
478→        setInitialLoadDone(true);
479→
480→        // Auto-select the first agent on initial load when nothing is selected
481→        setActiveAgentId((prev) => {
482→          if (prev !== null) return prev;
483→          if (serverAgents.length === 0) return null;
484→          return serverAgents[0].agentId;
485→        });
486→        return;
487→      }
488→
489→      // ── spawned: auto-select the newly created agent ──
490→      if (data.type === "spawned") {
491→        setActiveAgentId(data.agentId);
492→        return;
493→      }
494→
495→      // ── status: update a specific agent's status ──
496→      if (data.type === "status") {
497→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
498→        return;
499→      }
500→
501→      // ── error: append to agent's message list ──
502→      if (data.type === "error") {
503→        updateAgent(data.agentId, (prev) => ({
504→          ...prev,
505→          messages: [
506→            ...prev.messages,
507→            {
508→              id: nextId(),
509→              role: "system",
510→              content: `Error: ${data.error}`,
511→              timestamp: Date.now(),
512→            },
513→          ],
514→        }));
515→        // Track processed count for dedup
516→        processedCountRef.current.set(
517→          data.agentId,
518→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
519→        );
520→        return;
521→      }
522→
523→      // ── relay: append claude message to agent's history ──
524→      if (data.type === "relay") {
525→        const agentId = data.agentId;
526→        const rawMsg = data.message;
527→        const chatMsg = relayChatMessage(agentId, data);
528→
529→        updateAgent(agentId, (prev) => ({
530→          ...prev,
531→          rawMessages: [...prev.rawMessages, rawMsg],
532→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
533→        }));
534→        if (chatMsg) {
535→          // Track processed count for dedup
536→          processedCountRef.current.set(
537→            agentId,
538→            (processedCountRef.current.get(agentId) ?? 0) + 1
539→          );
540→        }
541→        return;
542→      }
543→    };
544→  }, [updateAgent]);
545→
546→  useEffect(() => {
547→    closingRef.current = false;
548→    connect();
549→    return () => {
550→      closingRef.current = true;
551→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
552→      wsRef.current?.close();
553→    };
554→  }, [connect]);
555→
556→  const send = useCallback((data: object) => {
557→    if (wsRef.current?.readyState === WebSocket.OPEN) {
558→      wsRef.current.send(JSON.stringify(data));
559→    }
560→  }, []);
561→
562→  // Request history for the active agent if not already loaded.
563→  useEffect(() => {
564→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
565→    log("requesting history for", activeAgentId);
566→    send({ type: "request_history", agentId: activeAgentId });
567→  }, [activeAgentId, loadedAgents, send]);
568→
569→  const spawnAgent = useCallback(
570→    (prompt: string) => {
571→      send({ type: "spawn", prompt });
572→    },
573→    [send]
574→  );
575→
576→  const sendMessage = useCallback(
577→    (content: string) => {
578→      if (!activeAgentId) return;
579→      // Optimistically add user message to local state
580→      updateAgent(activeAgentId, (prev) => ({
581→        ...prev,
582→        messages: [
583→          ...prev.messages,
584→          {
585→            id: nextId(),
586→            role: "user",
587→            content,
588→            timestamp: Date.now(),
589→          },
590→        ],
591→      }));
592→      send({ type: "send_message", agentId: activeAgentId, content });
593→    },
594→    [send, activeAgentId, updateAgent]
595→  );
596→
597→  const respondToControl = useCallback(
598→    (requestId: string, allow: boolean) => {
599→      if (!activeAgentId) return;
600→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
601→      updateAgent(activeAgentId, (prev) => ({
602→        ...prev,
603→        messages: prev.messages.map((m) =>
604→          m.controlRequest?.id === requestId
605→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
606→            : m
607→        ),
608→      }));
609→    },
610→    [send, activeAgentId, updateAgent]
611→  );
612→
613→  /** Respond to an AskUserQuestion control request with the user's selections. */
614→  const respondToUserQuestion = useCallback(
615→    (requestId: string, answers: Record<string, string>) => {
616→      if (!activeAgentId) return;
617→      send({
618→        type: "control_response",
619→        agentId: activeAgentId,
620→        request_id: requestId,
621→        allow: true,
622→        answers,
623→      });
624→      updateAgent(activeAgentId, (prev) => ({
625→        ...prev,
626→        messages: prev.messages.map((m) =>
627→          m.userQuestion?.requestId === requestId
628→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
629→            : m
630→        ),
631→      }));
632→    },
633→    [send, activeAgentId, updateAgent]
634→  );
635→
636→  // ── Agent management actions ──────────────────────────────────────────────
637→
638→  const killAgent = useCallback(
639→    (agentId: string) => {
640→      send({ type: "kill_agent", agentId });
641→    },
642→    [send]
643→  );
644→
645→  const deleteAgent = useCallback(
646→    (agentId: string) => {
647→      send({ type: "delete_agent", agentId });
648→      // Deselect if we just deleted the active agent
649→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
650→    },
651→    [send]
652→  );
653→
654→  const renameAgent = useCallback(
655→    (agentId: string, label: string) => {
656→      send({ type: "rename_agent", agentId, label });
657→    },
658→    [send]
659→  );
660→
661→  const clearHistory = useCallback(
662→    (agentId: string) => {
663→      send({ type: "clear_history", agentId });
664→    },
665→    [send]
666→  );
667→
668→  // ── Task actions ──────────────────────────────────────────────────────────
669→
670→  const createTask = useCallback(
671→    (title: string, description: string, priority: TaskPriority) => {
672→      send({ type: "create_task", title, description, priority });
673→    },
674→    [send]
675→  );
676→
677→  const updateTask = useCallback(
678→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
679→      send({ type: "update_task", taskId, updates });
680→    },
681→    [send]
682→  );
683→
684→  const deleteTask = useCallback(
685→    (taskId: string) => {
686→      send({ type: "delete_task", taskId });
687→    },
688→    [send]
689→  );
690→
691→  const delegateTask = useCallback(
692→    (taskId: string) => {
693→      send({ type: "delegate_task", taskId });
694→    },
695→    [send]
696→  );
697→
698→  // Derived values for the active agent
699→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
700→  const activeStatus = useMemo<AgentStatus>(
701→    () => activeAgent?.status ?? "idle",
702→    [activeAgent?.status]
703→  );
704→  const activeMessages = useMemo<ChatMessage[]>(
705→    () => activeAgent?.messages ?? [],
706→    [activeAgent?.messages]
707→  );
708→  const activeRawMessages = useMemo<ClaudeMessage[]>(
709→    () => activeAgent?.rawMessages ?? [],
710→    [activeAgent?.rawMessages]
711→  );
712→  const historyLoading = activeAgentId !== null && !loadedAgents.has(activeAgentId);
713→
714→  return {
715→    connected,
716→    initialLoadDone,
717→    historyLoading,
718→    agents,
719→    agentOrder,
720→    activeAgentId,
721→    setActiveAgentId,
722→    activeStatus,
723→    activeMessages,
724→    activeRawMessages,
725→    spawnAgent,
726→    sendMessage,
727→    respondToControl,
728→    respondToUserQuestion,
729→    killAgent,
730→    deleteAgent,
731→    renameAgent,
732→    clearHistory,
733→    tasks,
734→    createTask,
735→    updateTask,
736→    deleteTask,
737→    delegateTask,
738→  };
739→}
740→

